func (c *Context) Stream(step func(w http.ResponseWriter)) {
	w := c.Writer
	clientGone := w.CloseNotify()
	for {
		select {
		case <-clientGone:
			return
		default:
			step(w)
			w.Flush()
		}
	}
}

